from pathlib import Path
import hashlib, json, os, resource, signal, subprocess, time

r = Path.cwd()
b = r / 'build/qbe-classes'
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def execute(command, timeout=30):
    def limit(): resource.setrlimit(resource.RLIMIT_AS, (4*1024**3, 4*1024**3))
    start = time.monotonic()
    p = subprocess.Popen([str(x) for x in command], cwd=r, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE, start_new_session=True, preexec_fn=limit)
    timed_out = False
    try: out, err = p.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        timed_out = True
        os.killpg(p.pid, signal.SIGKILL)
        out, err = p.communicate()
    return {'command': [str(x) for x in command], 'seconds': time.monotonic()-start,
            'returncode': p.returncode, 'timed_out': timed_out,
            'stdout': out.decode(errors='replace'), 'stderr': err.decode(errors='replace')}

if __name__ == '__main__':
    cases = [('class_method_return_conformance', True), ('wide_class_abi_conformance', True),
             ('inheritance_conformance', True), ('class_module_smoke', True),
             ('origin_function_conformance', True), ('private_class_negative', False),
             ('inheritance_cycle_negative', False), ('origin_without_parent_negative', False)]
    report = {'base_revision': '07a9e45f7199ad9c0cda7078cd6bea3093642299',
              'scope': 'Unchanged maintained class tests versus installed 0.8.9 before class lowering changes',
              'manifest': json.loads((b/'baseline-manifest.json').read_text()), 'cases': []}
    for name, positive in cases:
        source = r/'tests'/(name+'.lsl')
        row = {'source': str(source.relative_to(r)), 'source_sha256': sha(source),
               'positive': positive, 'runs': []}
        report['cases'].append(row)
        for kind, compiler in [('v089', Path('/home/antonin/.local/bin/lslc')), ('before', b/'frontend-before')]:
            output = b/(name+'-'+kind)
            command = [compiler, source, output] + ([b/'backend-before'] if kind=='before' else [])
            build = execute(command)
            result = {'kind': kind, 'build': build}
            row['runs'].append(result)
            if build['returncode'] == 0:
                result['binary_sha256'] = sha(output)
                result['execution'] = execute([output])
            if positive:
                expected_file = source.with_suffix('.out')
                expected = expected_file.read_text() if expected_file.exists() else None
                result['matches_expected'] = build['returncode'] == 0 and result['execution']['returncode'] == 0
                if expected is not None:
                    result['expected'] = expected
                    result['matches_expected'] &= result.get('execution',{}).get('stdout') == expected
            else:
                result['matches_expected'] = build['returncode'] != 0 and not build['timed_out']
            print(name, kind, 'PASS' if result['matches_expected'] else 'FAIL', flush=True)
            (b/'baseline-audit.json').write_text(json.dumps(report, indent=2)+'\n')
    report['old_controls_pass'] = all(c['runs'][0]['matches_expected'] for c in report['cases'])
    report['complete'] = True
    report['driver_sha256'] = sha(Path(__file__))
    (b/'baseline-audit.json').write_text(json.dumps(report, indent=2)+'\n')
